contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(bytes32 role, bytes32 id, uint256 delay) public {
        c.grantRole(c.PROPOSER_ROLE(), address(this));
        c.schedule(address(0), 0, "", bytes32(0), id, delay);
        bool reverted;
        try c.cancel(id) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted || (!c.isOperation(id) && !c.isOperationPending(id) && c.getTimestamp(id) == 0));
    }
}
